39	function readAsDataUrl(file: File): Promise<string> {
40	  return new Promise((resolve, reject) => {
41	    const reader = new FileReader();
42	    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
43	    reader.onerror = () => reject(reader.error ?? new Error('read failed'));
44	    reader.readAsDataURL(file);
45	  });
46	}
