  background: linear-gradient(90deg, var(--text-secondary) 0%, var(--text-primary) 50%, var(--text-secondary) 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  animation: turn-activity-shimmer var(--turn-activity-shimmer-duration) linear infinite;
}
@keyframes turn-activity-shimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .turn-activity-text.shimmer { animation: none; color: var(--text-secondary); background: none; }
  .turn-activity-spinner { animation: none; }
}
