def sc(msg):
    """structuredContent, or the parsed text block when a legacy version strips it."""
    if msg is None:
        return {"<timeout>": True}
    if "error" in msg:
        return {"<rpc-error>": msg["error"]}
    r = msg["result"]
    if "structuredContent" in r:
        return r["structuredContent"]
    for c in r.get("content", []):
        if c.get("type") == "text":
            try:
                return json.loads(c["text"])
            except Exception:
                return {"<text>": c["text"]}
    return r


